import React from 'react';
import { GraduationCap, ArrowUpRight } from 'lucide-react';
import SectionHeading from './SectionHeading';
import Reveal from './Reveal';
import { background } from '../data/content';

export default function Background() {
  const { education } = background;

  return (
    <section id="background" className="py-20 px-4 sm:px-6">
      <div className="max-w-6xl mx-auto">
        <Reveal>
          <SectionHeading eyebrow={background.eyebrow} heading={background.heading} />
        </Reveal>

        <div className="mt-8 grid lg:grid-cols-2 gap-4">
          <Reveal delay={80}>
            <div className="h-full rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-6 sm:p-8">
              <div className="inline-flex items-center justify-center w-9 h-9 rounded-lg bg-indigo-500/10 text-indigo-500 dark:text-indigo-400 mb-3">
                <GraduationCap size={18} />
              </div>
              <h3 className="font-display text-xl font-semibold text-zinc-900 dark:text-zinc-50">
                {education.degree}
              </h3>
              <p className="mt-1 text-zinc-600 dark:text-zinc-400">{education.school}</p>
              <p className="mt-1 text-sm text-zinc-500 dark:text-zinc-500">{education.minor}</p>
              <div className="mt-4 inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-mono bg-zinc-100 dark:bg-zinc-800 text-zinc-600 dark:text-zinc-400">
                GPA · {education.gpa}
              </div>
            </div>
          </Reveal>

          <Reveal delay={160}>
            <div className="h-full rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-6 sm:p-8 flex flex-col">
              <h3 className="font-display text-xl font-semibold text-zinc-900 dark:text-zinc-50">
                Previously
              </h3>
              <div className="mt-4 flex flex-wrap gap-2">
                {background.previously.map((item) => (
                  <span
                    key={item.company}
                    className="px-3 py-1.5 rounded-full text-xs font-mono border border-zinc-200 dark:border-zinc-800 text-zinc-600 dark:text-zinc-400"
                    title={item.role}
                  >
                    {item.company} <span className="text-zinc-400 dark:text-zinc-600">·</span> {item.role}
                  </span>
                ))}
              </div>
              <p className="mt-4 text-sm text-zinc-500 dark:text-zinc-500">{background.note}</p>
              <a
                href={background.cta.href}
                target="_blank"
                rel="noopener noreferrer"
                className="mt-auto pt-4 inline-flex items-center gap-1.5 text-sm font-medium text-indigo-600 dark:text-indigo-400 hover:underline"
              >
                {background.cta.label}
                <ArrowUpRight size={15} />
              </a>
            </div>
          </Reveal>
        </div>
      </div>
    </section>
  );
}
